PRAGMA foreign_keys=ON;
CREATE TABLE merchant_api_clients(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'disabled',rate_limit_per_minute INTEGER NOT NULL DEFAULT 60,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE merchant_api_keys(id TEXT PRIMARY KEY,client_id TEXT NOT NULL REFERENCES merchant_api_clients(id),key_prefix TEXT NOT NULL,key_hash TEXT NOT NULL UNIQUE,expires_at TEXT,revoked_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE merchant_api_scopes(client_id TEXT NOT NULL REFERENCES merchant_api_clients(id),scope TEXT NOT NULL CHECK(scope IN('products:read','products:write','inventory:read','inventory:write','orders:read','orders:write','customers:read','coupons:read','shipments:read','payments:read','webhooks:manage')),PRIMARY KEY(client_id,scope));
CREATE TABLE merchant_api_usage(client_id TEXT NOT NULL,minute_bucket TEXT NOT NULL,request_count INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(client_id,minute_bucket));
CREATE TABLE merchant_webhook_endpoints(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,url TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'disabled',secret_hash TEXT NOT NULL,encrypted_secret TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE merchant_webhook_subscriptions(endpoint_id TEXT NOT NULL REFERENCES merchant_webhook_endpoints(id),event_type TEXT NOT NULL,PRIMARY KEY(endpoint_id,event_type));
CREATE TABLE merchant_webhook_deliveries(id TEXT PRIMARY KEY,endpoint_id TEXT NOT NULL REFERENCES merchant_webhook_endpoints(id),event_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',attempt_count INTEGER NOT NULL DEFAULT 0,next_attempt_at TEXT,response_status INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(endpoint_id,event_id));
CREATE TABLE merchant_webhook_failures(id TEXT PRIMARY KEY,delivery_id TEXT NOT NULL REFERENCES merchant_webhook_deliveries(id),attempt_no INTEGER NOT NULL,error_code TEXT,next_attempt_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE merchant_api_audit_logs(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,client_id TEXT,action TEXT NOT NULL,resource_type TEXT,resource_id TEXT,metadata TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_webhook_retry ON merchant_webhook_deliveries(status,next_attempt_at);
